Repair the complete source below and return one corrected source file. `AuditTrail` subscribes once to an `AuditSource` during construction. Append events add a unique entry, revise events replace the matching entry's text, and remove events delete it; events targeting missing IDs do nothing. Duplicate append IDs do nothing. `entries()` returns fresh objects ordered by ascending sequence, then ascending ID. `dispose()` must unsubscribe exactly once and be idempotent; after disposal, source emissions must not alter the trail. Initial entries must be snapshotted without aliasing. Here is the known-bad source:

export interface AuditEntry { readonly id: string; readonly sequence: number; readonly text: string; }
export type AuditEvent =
  | { readonly type: 'append'; readonly entry: AuditEntry }
  | { readonly type: 'revise'; readonly id: string; readonly text: string }
  | { readonly type: 'remove'; readonly id: string };
export interface AuditSource { subscribe(listener: (event: AuditEvent) => void): () => void; }

export class AuditTrail {
  private entriesById = new Map<string, AuditEntry>();
  private readonly unsubscribe: () => void;
  private disposed = false;

  constructor(source: AuditSource, initial: readonly AuditEntry[] = []) {
    for (const entry of initial) if (!this.entriesById.has(entry.id)) this.entriesById.set(entry.id, { ...entry });
    this.unsubscribe = source.subscribe(event => this.apply(event));
  }

  private apply(event: AuditEvent): void {
    if (this.disposed) return;
    if (event.type === 'append') {
      if (!this.entriesById.has(event.entry.id)) this.entriesById.set(event.entry.id, { ...event.entry });
    } else if (event.type === 'revise') {
      const current = this.entriesById.get(event.id);
      if (current) this.entriesById.set(event.id, { ...current, text: event.text });
    } else {
      this.entriesById.delete(event.id);
    }
  }

  entries(): AuditEntry[] {
    return [...this.entriesById.values()]
      .sort((a, b) => a.sequence - b.sequence || a.id.localeCompare(b.id))
      .map(entry => ({ ...entry }));
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
  }
}

