import { AuditEntry, AuditEvent, AuditSource, AuditTrail } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

let listener: ((event: AuditEvent) => void) | undefined;
let subscribeCount = 0;
let unsubscribeCount = 0;
const source: AuditSource = {
  subscribe(next): () => void {
    subscribeCount++;
    listener = next;
    return () => { unsubscribeCount++; };
  },
};

const initial: AuditEntry[] = [
  { id: 'b', sequence: 2, text: 'second' },
  { id: 'a', sequence: 1, text: 'first' },
  { id: 'duplicate', sequence: 5, text: 'kept' },
  { id: 'duplicate', sequence: 0, text: 'ignored' },
];
const trail = new AuditTrail(source, initial);
assert(subscribeCount === 1, 'construction should subscribe exactly once');
initial[0] = { id: 'changed', sequence: 99, text: 'changed' };
(initial[1] as { text: string }).text = 'mutated';

let entries = trail.entries();
assert(entries.map(entry => entry.id).join(',') === 'a,b,duplicate', 'initial entries should be snapshotted, deduplicated, and sorted');
assert(entries[0].text === 'first', 'initial entry objects should not be aliased');

listener!({ type: 'append', entry: { id: 'c', sequence: 2, text: 'third' } });
listener!({ type: 'append', entry: { id: 'a', sequence: 99, text: 'duplicate append' } });
entries = trail.entries();
assert(entries.map(entry => entry.id).join(',') === 'a,b,c,duplicate', 'entries should sort by sequence and then ID');
assert(entries.find(entry => entry.id === 'a')!.text === 'first', 'duplicate append IDs should do nothing');

const appended = { id: 'd', sequence: 3, text: 'snapshotted append' };
listener!({ type: 'append', entry: appended });
(appended as { text: string }).text = 'mutated outside';
assert(trail.entries().find(entry => entry.id === 'd')!.text === 'snapshotted append', 'append events should snapshot their entry');

listener!({ type: 'revise', id: 'b', text: 'revised' });
listener!({ type: 'revise', id: 'missing', text: 'ignored' });
assert(trail.entries().find(entry => entry.id === 'b')!.text === 'revised', 'revise should replace matching text');
assert(trail.entries().length === 5, 'revise targeting a missing ID should do nothing');

listener!({ type: 'remove', id: 'c' });
listener!({ type: 'remove', id: 'missing' });
assert(!trail.entries().some(entry => entry.id === 'c'), 'remove should delete the matching entry');
assert(trail.entries().length === 4, 'remove targeting a missing ID should do nothing');

const first = trail.entries();
const second = trail.entries();
assert(first !== second && first[0] !== second[0], 'entries should return a fresh array and fresh objects');
(first[0] as { text: string }).text = 'damaged';
first.splice(0, first.length);
assert(trail.entries()[0].text !== 'damaged' && trail.entries().length === 4, 'returned entries must not expose internal state');

trail.dispose();
assert(unsubscribeCount === 1, 'dispose should unsubscribe once');
trail.dispose();
assert(unsubscribeCount === 1, 'dispose should be idempotent');
const beforeDisposedEmission = JSON.stringify(trail.entries());
listener!({ type: 'append', entry: { id: 'after', sequence: 0, text: 'after disposal' } });
listener!({ type: 'revise', id: 'a', text: 'after disposal' });
listener!({ type: 'remove', id: 'b' });
assert(JSON.stringify(trail.entries()) === beforeDisposedEmission, 'emissions after disposal must not alter the trail');

